/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "args">args</param>
static void main(Args args)
{
    AVAERPriceListToAzureBlobInBatch    AVAERPriceListToAzureBlobInBatch;
    ;
    AVAERPriceListToAzureBlobInBatch = AVAERPriceListToAzureBlobInBatch::construct();

    FormRun                 formRun = args.caller();
    FormDataSource          fds_priceDiscGroup = formRun.dataSource(formDataSourceStr(AVAPriceIncreaseTable,PriceDiscGroup));
    MultiSelectionHelper    helper = MultiSelectionHelper::construct();
    PriceDiscGroup          priceDiscGroup;
    String255                     priceGroupFilterStr;

    helper.parmDatasource(fds_priceDiscGroup);

    priceDiscGroup = helper.getFirst();
    while (priceDiscGroup.RecId != 0)
    {
        if (priceGroupFilterStr != '')
        {
            priceGroupFilterStr += ',';
        }
        priceGroupFilterStr +=  priceDiscGroup.GroupId;
        priceDiscGroup = helper.getNext();
    }

    AVAERPriceListToAzureBlobInBatch.parmpriceGroupFilterStr1(priceGroupFilterStr);
    AVAERPriceListToAzureBlobInBatch.pack();
    if (AVAERPriceListToAzureBlobInBatch.prompt())
    {
        AVAERPriceListToAzureBlobInBatch.parmpriceGroupFilterStr1(priceGroupFilterStr);
        AVAERPriceListToAzureBlobInBatch.runOperation();
    }
}

